CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS companies(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,email TEXT NOT NULL,role TEXT NOT NULL,password_hash TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,email));
CREATE TABLE IF NOT EXISTS agents(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,role TEXT NOT NULL,system_instructions TEXT NOT NULL DEFAULT '',permissions JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS task_dependencies(task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,depends_on_task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,PRIMARY KEY(task_id,depends_on_task_id));
CREATE TABLE IF NOT EXISTS messages(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,task_id UUID REFERENCES tasks(id) ON DELETE SET NULL,sender_agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,receiver_agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tool_executions(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,action TEXT NOT NULL,resource TEXT,arguments JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL,result JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS notifications(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID REFERENCES employees(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,project_id UUID REFERENCES projects(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'TODO',assigned_agent_id UUID REFERENCES agents(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memories(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,scope TEXT NOT NULL CHECK(scope IN ('PRIVATE','PROJECT','TEAM','COMPANY')),content TEXT NOT NULL,embedding vector(1536),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,task_id UUID REFERENCES tasks(id) ON DELETE SET NULL,execution_id UUID UNIQUE REFERENCES tool_executions(id) ON DELETE SET NULL,action TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',decided_by UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),decided_at TIMESTAMPTZ);
ALTER TABLE approvals ADD COLUMN IF NOT EXISTS execution_id UUID UNIQUE REFERENCES tool_executions(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS audit_logs(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,actor_id UUID,agent_id UUID,action TEXT NOT NULL,resource TEXT,metadata JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,permissions JSONB NOT NULL DEFAULT '[]',UNIQUE(company_id,name));
CREATE TABLE IF NOT EXISTS employee_roles(employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,role_id UUID NOT NULL REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(employee_id,role_id));
CREATE TABLE IF NOT EXISTS conversations(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,title TEXT NOT NULL DEFAULT 'New conversation',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_messages(id UUID PRIMARY KEY,conversation_id UUID NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender TEXT NOT NULL CHECK(sender IN ('USER','AGENT','SYSTEM')),content TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_runs(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,conversation_id UUID REFERENCES conversations(id) ON DELETE SET NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'RUNNING',current_step INTEGER NOT NULL DEFAULT 0,max_steps INTEGER NOT NULL DEFAULT 5,results JSONB NOT NULL DEFAULT '[]',waiting_execution_id UUID REFERENCES tool_executions(id) ON DELETE SET NULL,waiting_approval_id UUID REFERENCES approvals(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS agent_runs_company_idx ON agent_runs(company_id,created_at DESC);
CREATE INDEX IF NOT EXISTS agent_runs_waiting_execution_idx ON agent_runs(waiting_execution_id) WHERE waiting_execution_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS agent_runs_employee_idx ON agent_runs(employee_id,created_at DESC);
CREATE INDEX IF NOT EXISTS memories_agent_idx ON memories(agent_id);
CREATE INDEX IF NOT EXISTS memories_company_idx ON memories(company_id);
CREATE INDEX IF NOT EXISTS tasks_company_idx ON tasks(company_id);
CREATE INDEX IF NOT EXISTS audit_company_idx ON audit_logs(company_id);
CREATE INDEX IF NOT EXISTS memories_embedding_idx ON memories USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS tool_executions_company_idx ON tool_executions(company_id,created_at DESC);
CREATE INDEX IF NOT EXISTS conversations_employee_idx ON conversations(employee_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS conversations_agent_idx ON conversations(agent_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS conversation_messages_conversation_idx ON conversation_messages(conversation_id,created_at);

CREATE TABLE IF NOT EXISTS devices(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,name TEXT NOT NULL,platform TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OFFLINE',token_hash TEXT NOT NULL UNIQUE,capabilities JSONB NOT NULL DEFAULT '[]',last_seen_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS device_agent_bindings(device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,permissions JSONB NOT NULL DEFAULT '[]',active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(device_id,agent_id));
CREATE TABLE IF NOT EXISTS device_commands(id UUID PRIMARY KEY,company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE,action TEXT NOT NULL,arguments JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'QUEUED',result JSONB,approval_id UUID REFERENCES approvals(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ);
